package com.vehiclerental.mak.auth.integration;
import com.vehiclerental.mak.auth.entity.*;import com.vehiclerental.mak.auth.repository.*;import com.vehiclerental.mak.auth.service.*;import com.vehiclerental.mak.auth.dto.request.*;import com.vehiclerental.mak.auth.security.*;import com.vehiclerental.mak.common.exception.ApiException;import com.vehiclerental.mak.notifications.email.service.EmailService;
import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.transaction.annotation.Transactional;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.web.context.WebApplicationContext;import org.springframework.mock.web.MockHttpSession;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextImpl;import org.springframework.jdbc.core.JdbcTemplate;import org.mockito.ArgumentCaptor;
import java.util.*;import java.time.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
@SpringBootTest @Transactional
class CustomRoleTests{
 @Autowired RoleService roles;@Autowired AccountService service;@Autowired AccountRepository accounts;@Autowired CustomRoleRepository roleRecords;@Autowired AuthControlRepository controls;@Autowired AuthAuditRepository audits;@Autowired InvitationRepository invitations;@Autowired WebApplicationContext context;@Autowired JdbcTemplate jdbc;
 private Account admin;private MockMvc mvc;
 @BeforeEach void setup(){controls.findById(1).orElseThrow().setBootstrapDone(true);admin=account("Admin",null);mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();}
 private Account account(String role,Long roleId){var a=new Account();a.setName("Role Test");a.setEmail("role-"+UUID.randomUUID()+"@example.com");a.setPasswordHash("not-a-login-password");a.setRole(role);a.setCustomRoleId(roleId);a.setStatus("Active");a.setCreatedAt(Instant.now());return accounts.saveAndFlush(a);}
 private MockHttpSession session(Account a){var s=new MockHttpSession();s.setAttribute("SPRING_SECURITY_CONTEXT",new SecurityContextImpl(UsernamePasswordAuthenticationToken.authenticated(new AccountPrincipal(a.getId(),a.getSessionVersion()),null,service.permissions(a).stream().map(org.springframework.security.core.authority.SimpleGrantedAuthority::new).toList())));return s;}
 private Map<String,Object> role(List<String> permissions){return new LinkedHashMap<>(Map.of("name","Finance custom "+UUID.randomUUID(),"description","Billing access","permissions",permissions,"version",0));}
 private long id(Map<String,Object> r){return ((Number)r.get("id")).longValue();}
 @Test void customRolesPersistRejectUnknownPermissionsAndStaleSavesRevokeSessions(){var data=role(List.of("invoices.read","invoices.create","invoices.edit","invoices.issue"));var saved=roles.save(null,data,admin.getId());long id=id(saved);var person=account("Viewer",id);var old=new AccountPrincipal(person.getId(),0);assertTrue(service.permissions(person).contains("invoices.issue"));var changed=new LinkedHashMap<String,Object>(saved);changed.put("permissions",List.of("invoices.read"));roles.save(id,changed,admin.getId());assertNull(service.active(old));assertFalse(service.permissions(accounts.findById(person.getId()).orElseThrow()).contains("invoices.issue"));assertThrows(ApiException.class,()->roles.save(id,changed,admin.getId()));var bad=role(List.of("unknown.permission"));assertThrows(ApiException.class,()->roles.save(null,bad,admin.getId()));assertThrows(ApiException.class,()->roles.save(null,role(List.of("invoices.issue")),admin.getId()));}
 @Test void apiChecksSeparateDraftCreateIssueCreditRefundAndBankChanges()throws Exception{var saved=roles.save(null,role(List.of("invoices.read","invoices.create","invoices.edit")),admin.getId());var person=account("Viewer",id(saved));var session=session(person);mvc.perform(get("/api/invoices").session(session)).andExpect(status().isOk());mvc.perform(post("/api/invoices?issue=true").session(session).with(csrf().asHeader()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(post("/api/invoices/99999/credit-notes").session(session).with(csrf().asHeader()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(post("/api/invoices/99999/payments").session(session).with(csrf().asHeader()).contentType("application/json").content("{\"kind\":\"Refund\"}")).andExpect(status().isForbidden());mvc.perform(put("/api/invoices/billing-profile").session(session).with(csrf().asHeader()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(get("/api/users/role-definitions").session(session)).andExpect(status().isForbidden());}
 @Test void moduleCreateDoesNotImplyEditOrArchive()throws Exception{var role=roles.save(null,role(List.of("fleet.read","fleet.create")),admin.getId());var session=session(account("Viewer",id(role)));mvc.perform(post("/api/vehicles").session(session).with(csrf().asHeader()).contentType("application/json").content("{}")).andExpect(status().isBadRequest());mvc.perform(put("/api/vehicles/99999").session(session).with(csrf().asHeader()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(delete("/api/vehicles/99999").session(session).with(csrf().asHeader())).andExpect(status().isForbidden());}
 @Test void memberAssignmentRejectsStaleFormsAndLastAdminCustomReassignment(){var saved=roles.save(null,role(List.of("fleet.read")),admin.getId());var person=account("Viewer",null);service.update(admin.getId(),person.getId(),new AccountAccessRequest("Viewer","Active",id(saved),0L));assertEquals(saved.get("name"),service.response(person).get("role"));assertThrows(ApiException.class,()->service.update(admin.getId(),person.getId(),new AccountAccessRequest("Finance","Active",null,0L)));jdbc.update("update auth_accounts set status='Inactive' where role='Admin' and id<>?",admin.getId());assertThrows(ApiException.class,()->service.update(admin.getId(),admin.getId(),new AccountAccessRequest("Viewer","Active",id(saved),0L)));}
 @Test void invitationTokensArePrivateSingleUseAndEmailBound(){var email=mock(EmailService.class);var sender=new InvitationService(invitations,accounts,controls,audits,roles,email,true,"http://localhost:5173");var result=sender.invite(Map.of("name","Invited Guest","email","invited-"+UUID.randomUUID()+"@example.com","role","Viewer"),admin.getId());assertFalse(result.containsKey("token"));var url=ArgumentCaptor.forClass(String.class);verify(email).staffInvitation(anyLong(),anyString(),anyString(),eq("Viewer"),url.capture(),any(java.time.Instant.class));String token=url.getValue().substring(url.getValue().indexOf("invitation=")+11);assertEquals(result.get("email"),sender.preview(token).get("email"));var a=new Account();assertThrows(ApiException.class,()->sender.accept(token,"other@example.com",a));sender.accept(token,result.get("email").toString(),a);assertEquals("Active",a.getStatus());assertThrows(ApiException.class,()->sender.preview(token));}
 @Test void builtInDefinitionsCannotBeOverwrittenAndAdminCatalogRemainsUsable()throws Exception{assertTrue(roles.list().stream().filter(r->Boolean.TRUE.equals(r.get("builtIn"))).count()==5);var data=role(List.of("fleet.read"));data.put("name","Admin");assertThrows(ApiException.class,()->roles.save(null,data,admin.getId()));mvc.perform(get("/api/users/role-definitions").session(session(admin))).andExpect(status().isOk()).andExpect(jsonPath("$.roles[0].name").value("Admin"));}
}
